#!/bin/sh
# Builds standalone.user.js: a self-contained user script (no CDN needed) for
# Strava's new map engine, with layers.js and fix-fatmap.js inlined.

set -eu
cd "$(dirname "$0")"

version=$(sed -n 's/.*"version": *"\([^"]*\)".*/\1/p' manifest.json)

{
	cat <<EOF
// ==UserScript==
// @name        strava-map-switcher (new map engine)
// @description Map switcher for Strava's route builder and Maps (Strava's own map engine)
// @version     ${version}-mre
// @match       https://www.strava.com/*
// @run-at      document-idle
// @grant       none
// ==/UserScript==

// Generated by build-userscript.sh from layers.js and fix-fatmap.js, do not edit.

(function () {
	const code = function () {
EOF
	cat layers.js
	echo
	cat fix-fatmap.js
	cat <<'EOF'
	};

	// run in the page context: the map engine is reachable only through the page's React objects
	const s = document.createElement('script');
	s.textContent = '(' + code + ')();';
	(document.head || document.documentElement).appendChild(s);
	s.remove();
})();
EOF
} > standalone.user.js

echo "built standalone.user.js"
